#' Wrapper function to generate parametric UMAP parameters
#'
#' @param local_connectivity Numeric. Number of nearest neighbours assumed to be
#' at distance zero. Defaults to `1.0`.
#' @param bandwidth Numeric. Convergence tolerance for smooth kNN distance
#' binary search. Defaults to `1e-05`.
#' @param mix_weight Numeric. Balance between fuzzy union and directed graph
#' during symmetrisation. Defaults to `1.0`.
#' @param hidden_layers Integer vector. Hidden layer sizes for the MLP encoder.
#' Defaults to `c(128L, 64L, 32L)`.
#' @param lr Numeric. Learning rate for the neural network optimiser. Defaults
#' to `0.001`.
#' @param corr_weight Numeric. Coefficient for the negative Pearson correlation
#' loss that encourages similar distances in embedding and original space.
#' Defaults to `0.0`.
#' @param n_epochs Integer. Number of training epochs. Defaults to `500L`.
#' @param batch_size Integer. Training batch size. Defaults to `256L`.
#' @param neg_sample_rate Integer. Number of negative samples per positive edge.
#' Defaults to `5L`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item local_connectivity - Numeric. Number of nearest neighbours assumed to
#'  be at distance zero. Defaults to `1.0`.
#'  \item bandwidth - Numeric. Convergence tolerance for smooth kNN distance
#'  binary search. Defaults to `1e-05`.
#'  \item mix_weight - Numeric. Balance between fuzzy union and directed graph
#'  during symmetrisation. Defaults to `1.0`.
#'  \item hidden_layers - Integer vector. Hidden layer sizes for the MLP
#'  encoder. Defaults to `c(128L, 64L, 32L)`.
#'  \item lr - Numeric. Learning rate for the neural network optimiser. Defaults
#'  to `0.001`.
#'  \item corr_weight - Numeric. Coefficient for the negative Pearson
#'  correlation loss that encourages similar distances in embedding and original
#'  space. Defaults to `0.0`.
#'  \item n_epochs - Integer. Number of training epochs. Defaults to `500L`.
#'  \item batch_size - Integer. Training batch size. Defaults to `256L`.
#'  \item neg_sample_rate - Integer. Number of negative samples per positive
#'  edge. Defaults to `5L`.
#' }
#'
#' @export
params_parametric_umap <- function(
  local_connectivity = 1.0,
  bandwidth = 1e-05,
  mix_weight = 1.0,
  hidden_layers = c(128L, 64L, 32L),
  lr = 0.001,
  corr_weight = 0.0,
  n_epochs = 500L,
  batch_size = 256L,
  neg_sample_rate = 5L
) {
  # Checks
  checkmate::qassert(local_connectivity, "N1")
  checkmate::qassert(bandwidth, "N1")
  checkmate::qassert(mix_weight, "N1")
  checkmate::qassert(hidden_layers, "X+[1,)")
  checkmate::qassert(lr, "N1(0,)")
  checkmate::qassert(corr_weight, "N1")
  checkmate::qassert(n_epochs, "I1[1,)")
  checkmate::qassert(batch_size, "I1[1,)")
  checkmate::qassert(neg_sample_rate, "I1[1,)")

  hidden_layers <- as.integer(hidden_layers)

  # Return
  list(
    local_connectivity = local_connectivity,
    bandwidth = bandwidth,
    mix_weight = mix_weight,
    hidden_layers = hidden_layers,
    lr = lr,
    corr_weight = corr_weight,
    n_epochs = n_epochs,
    batch_size = batch_size,
    neg_sample_rate = neg_sample_rate
  )
}

#' Wrapper function to generate PHATE parameters (GPU version)
#'
#' @param decay Numeric or `NULL`. Alpha decay exponent of the kernel. Higher
#' values give sharper transitions. `NULL` gives a binary connectivity kernel.
#' Defaults to `40.0`.
#' @param bandwidth_scale Numeric. Multiplicative factor on the kernel
#' bandwidth. Defaults to `1.0`.
#' @param thresh Numeric. Affinities below this are set to zero. Neighbours past
#' `k` join the kernel while their affinity clears it. Defaults to `1e-04`.
#' @param graph_symmetry String. How to symmetrise the affinity graph. One of
#' `c("additive", "multiplicative", "mnn", "none")`. Defaults to `"additive"`.
#' @param n_landmarks Integer or `NULL`. Number of landmarks for the compressed
#' diffusion operator. `NULL`, or a value of at least the number of samples,
#' runs the full N x N operator, which gets painful fast. Defaults to `2048L`.
#' @param landmark_method String. How to select the landmarks. `"spectral"` runs
#' its randomised SVD and k-means on the GPU (or on MLX with `backend = "mlx"`).
#' One of `c("spectral", "random", "density")`. Defaults to `"spectral"`.
#' @param n_svd Integer or `NULL`. Singular vectors for spectral landmark
#' selection. If `NULL`, defaults to `100` on the Rust side. Defaults to `NULL`.
#' @param t_max Integer. Largest diffusion time the Von Neumann entropy knee
#' search considers. Defaults to `100L`.
#' @param t_custom Integer or `NULL`. Fixed diffusion time. If `NULL`, picks the
#' knee automatically. Defaults to `NULL`.
#' @param gamma Numeric. Informational distance constant. `1` is the log
#' potential. Defaults to `1.0`.
#' @param mds_method String. MDS algorithm for the final embedding. One of
#' `c("sgd_dense", "classic")`. Defaults to `"sgd_dense"`.
#' @param mds_iter Integer or `NULL`. Number of SGD-MDS iterations. If `NULL`,
#' the Rust side runs 300 below 1000 points, 500 below 5000 and 800 otherwise
#' (points being the landmarks when landmarks are used). Defaults to `NULL`.
#' @param randomised Boolean. Use randomised SVD for classic MDS (`mds_method =
#' "classic"`). SGD-MDS initialises from a randomised classic MDS either way.
#' Defaults to `TRUE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item decay - Numeric or `NULL`. Alpha decay exponent of the kernel. Higher
#'  values give sharper transitions. `NULL` gives a binary connectivity kernel.
#'  Defaults to `40.0`.
#'  \item bandwidth_scale - Numeric. Multiplicative factor on the kernel
#'  bandwidth. Defaults to `1.0`.
#'  \item thresh - Numeric. Affinities below this are set to zero. Neighbours
#'  past `k` join the kernel while their affinity clears it. Defaults to
#'  `1e-04`.
#'  \item graph_symmetry - String. How to symmetrise the affinity graph. One of
#'  `c("additive", "multiplicative", "mnn", "none")`. Defaults to `"additive"`.
#'  \item n_landmarks - Integer or `NULL`. Number of landmarks for the
#'  compressed diffusion operator. `NULL`, or a value of at least the number of
#'  samples, runs the full N x N operator, which gets painful fast. Defaults to
#'  `2048L`.
#'  \item landmark_method - String. How to select the landmarks. `"spectral"`
#'  runs its randomised SVD and k-means on the GPU (or on MLX with `backend =
#'  "mlx"`). One of `c("spectral", "random", "density")`. Defaults to
#'  `"spectral"`.
#'  \item n_svd - Integer or `NULL`. Singular vectors for spectral landmark
#'  selection. If `NULL`, defaults to `100` on the Rust side. Defaults to
#'  `NULL`.
#'  \item t_max - Integer. Largest diffusion time the Von Neumann entropy knee
#'  search considers. Defaults to `100L`.
#'  \item t_custom - Integer or `NULL`. Fixed diffusion time. If `NULL`, picks
#'  the knee automatically. Defaults to `NULL`.
#'  \item gamma - Numeric. Informational distance constant. `1` is the log
#'  potential. Defaults to `1.0`.
#'  \item mds_method - String. MDS algorithm for the final embedding. One of
#'  `c("sgd_dense", "classic")`. Defaults to `"sgd_dense"`.
#'  \item mds_iter - Integer or `NULL`. Number of SGD-MDS iterations. If `NULL`,
#'  the Rust side runs 300 below 1000 points, 500 below 5000 and 800 otherwise
#'  (points being the landmarks when landmarks are used). Defaults to `NULL`.
#'  \item randomised - Boolean. Use randomised SVD for classic MDS (`mds_method
#'  = "classic"`). SGD-MDS initialises from a randomised classic MDS either way.
#'  Defaults to `TRUE`.
#' }
#'
#' @references Moon, et al., Nat. Biotechnol., 2019
#'
#' @export
params_phate_gpu <- function(
  decay = 40.0,
  bandwidth_scale = 1.0,
  thresh = 1e-04,
  graph_symmetry = c("additive", "multiplicative", "mnn", "none"),
  n_landmarks = 2048L,
  landmark_method = c("spectral", "random", "density"),
  n_svd = NULL,
  t_max = 100L,
  t_custom = NULL,
  gamma = 1.0,
  mds_method = c("sgd_dense", "classic"),
  mds_iter = NULL,
  randomised = TRUE
) {
  graph_symmetry <- match.arg(graph_symmetry)
  landmark_method <- match.arg(landmark_method)
  mds_method <- match.arg(mds_method)

  # Checks
  checkmate::qassert(decay, c("N1(0,)", "0"))
  checkmate::qassert(bandwidth_scale, "N1(0,)")
  checkmate::qassert(thresh, "N1[0,)")
  checkmate::assertChoice(
    graph_symmetry,
    c("additive", "multiplicative", "mnn", "none")
  )
  checkmate::qassert(n_landmarks, c("I1[1,)", "0"))
  checkmate::assertChoice(landmark_method, c("spectral", "random", "density"))
  checkmate::qassert(n_svd, c("I1[1,)", "0"))
  checkmate::qassert(t_max, "I1[1,)")
  checkmate::qassert(t_custom, c("I1[1,)", "0"))
  checkmate::qassert(gamma, "N1[-1,1]")
  checkmate::assertChoice(mds_method, c("sgd_dense", "classic"))
  checkmate::qassert(mds_iter, c("I1[1,)", "0"))
  checkmate::qassert(randomised, "B1")

  # Return
  list(
    decay = decay,
    bandwidth_scale = bandwidth_scale,
    thresh = thresh,
    graph_symmetry = graph_symmetry,
    n_landmarks = n_landmarks,
    landmark_method = landmark_method,
    n_svd = n_svd,
    t_max = t_max,
    t_custom = t_custom,
    gamma = gamma,
    mds_method = mds_method,
    mds_iter = mds_iter,
    randomised = randomised
  )
}

#' Wrapper function for the GPU BBKNN parameters
#'
#' @description GPU counterpart to [bixverse::params_sc_bbknn()]. Same BBKNN
#' knobs, but the kNN block is the GPU one, see [params_knn_gpu_defaults()].
#'
#' @details
#' `k` in the GPU kNN block is rejected rather than silently ignored: it is set
#' by `neighbours_within_batch`. BBKNN builds one index per batch and queries
#' each with every cell, so `knn_method = "nndescent"` builds and beam searches
#' a CAGRA graph here.
#'
#' @param neighbours_within_batch Integer. Number of neighbours to consider per
#' batch. Defaults to `3L`.
#' @param set_op_mix_ratio Numeric. Mixing ratio between union (1.0) and
#' intersection (0.0). Defaults to `1.0`.
#' @param local_connectivity Numeric. UMAP connectivity computation parameter,
#' how many nearest neighbours of each cell are assumed to be fully connected.
#' Defaults to `1.0`.
#' @param trim Integer or `NULL`. Trim the neighbours of each cell to these many
#' top connectivities. May help with population independence and improve the
#' tidiness of clustering. If `NULL`, it defaults to `10 *
#' neighbours_within_batch`. Defaults to `NULL`.
#' @param knn List. Optional overrides for the kNN block. See
#' [params_knn_gpu_defaults()] for the available elements. Without `k`. Unknown
#' elements are an error. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item neighbours_within_batch - Integer. Number of neighbours to consider
#'  per batch. Defaults to `3L`.
#'  \item set_op_mix_ratio - Numeric. Mixing ratio between union (1.0) and
#'  intersection (0.0). Defaults to `1.0`.
#'  \item local_connectivity - Numeric. UMAP connectivity computation parameter,
#'  how many nearest neighbours of each cell are assumed to be fully connected.
#'  Defaults to `1.0`.
#'  \item trim - Integer or `NULL`. Trim the neighbours of each cell to these
#'  many top connectivities. May help with population independence and improve
#'  the tidiness of clustering. If `NULL`, it defaults to `10 *
#'  neighbours_within_batch`. Defaults to `NULL`.
#'  \item The elements of [params_knn_gpu_defaults()], overridden by `knn`,
#'  spliced in at this position.
#' }
#'
#' @references Polański, et al., Bioinformatics, 2020
#'
#' @export
params_sc_bbknn_gpu <- function(
  neighbours_within_batch = 3L,
  set_op_mix_ratio = 1.0,
  local_connectivity = 1.0,
  trim = NULL,
  knn = list()
) {
  # Checks
  checkmate::qassert(neighbours_within_batch, "I1[1,)")
  checkmate::qassert(set_op_mix_ratio, "N1[0,1]")
  checkmate::qassert(local_connectivity, "N1")
  checkmate::qassert(trim, c("I1[1,)", "0"))

  # Merge
  knn_base <- params_knn_gpu_defaults()
  knn_base["k"] <- NULL
  checkmate::assertSubset(names(knn), names(knn_base))
  knn <- utils::modifyList(knn_base, knn, keep.null = TRUE)

  # Return
  c(
    list(
      neighbours_within_batch = neighbours_within_batch,
      set_op_mix_ratio = set_op_mix_ratio,
      local_connectivity = local_connectivity,
      trim = trim
    ),
    knn
  )
}

#' Default parameters for GPU fast clustering
#'
#' @description GPU counterpart to [bixverse::params_sc_fast_cluster()]. Fast
#' clustering coarsens the cells with k-means, builds a graph over the centroids
#' and runs Louvain or Leiden on it. The community of each centroid is handed
#' back to its cells. Only the k-means (and the cell-mediated top-m search) run
#' on the GPU. The mini-batch k-means knobs are gone: the GPU k-means is
#' full-batch Lloyd's.
#'
#' @param n_centroids Integer or `NULL`. Number of k-means centroids. If `NULL`,
#' defaults to `floor(4 * sqrt(n_cells))`. Defaults to `NULL`.
#' @param k_means_iter Integer. Maximum number of k-means iterations. Defaults
#' to `50L`.
#' @param k_means_init String or `NULL`. Initialisation method. One of
#' `"random"`, `"parallel"` or `"plusplus"`. If `NULL`, picked on the Rust side
#' based on the number of centroids. Defaults to `NULL`.
#' @param fixed Boolean. Shall k-means run for a fixed number of iterations,
#' without checking for convergence. wgpu only; MLX always runs every iteration.
#' Defaults to `TRUE`.
#' @param quantise Boolean. Shall the data buffer be held at fp16 on the GPU.
#' Halves the buffer and helps when the assignment kernels are memory bound.
#' wgpu only. Defaults to `FALSE`.
#' @param dist String. Distance for the k-means and the centroid graph. One of
#' `c("euclidean", "cosine")`. Defaults to `"euclidean"`.
#' @param cell_mediated Boolean. Shall the cell-mediated centroid graph from
#' Secuer be built instead of the kNN graph on the centroids. Centroids are then
#' linked by the cells that sit near both, so two centroids that are close in
#' space but have no cells between them stay apart. If `TRUE`, `centroid_k` and
#' `centroid_graph` are ignored. Defaults to `FALSE`.
#' @param n_anchors Integer. Number of nearest centroids each cell links to in
#' the cell-mediated graph. Only used if `cell_mediated = TRUE`. Defaults to
#' `5L`.
#' @param centroid_k Integer. Neighbours per centroid in the exact centroid kNN.
#' Only used if `cell_mediated = FALSE`. Defaults to `15L`.
#' @param centroid_graph List. Optional overrides for how the centroid kNN is
#' turned into a graph. See [bixverse::params_knn_graph_defaults()]. Only used
#' if `cell_mediated = FALSE`. Defaults to `list()`.
#' @param algorithm String. Community detection on the centroid graph. One of
#' `c("louvain", "leiden")`. Defaults to `"louvain"`.
#' @param n_iterations Integer or `NULL`. Number of iterations of the community
#' detection. A negative value iterates until stable. If `NULL`, the bixverse
#' default for the chosen `algorithm`. Defaults to `NULL`.
#' @param beta Numeric. Leiden only. Randomness of the refinement step. Defaults
#' to `0.01`.
#' @param min_gain Numeric. With a negative `n_iterations`, also stop once an
#' iteration gains no more than this in modularity. Defaults to `0.0`.
#' @param local_moving String. `"queue"` is Traag's sequential queue.
#' `"coloured"` moves the nodes of one colour class in parallel, which only
#' kicks in on larger levels of the graph. One of `c("queue", "coloured")`.
#' Defaults to `"queue"`.
#' @param multi_level Boolean. Shall the communities be aggregated and refined
#' in levels. Defaults to `TRUE`.
#' @param max_evals Integer. Cap on the node evaluations per local moving phase,
#' in units of the number of nodes. Defaults to `10L`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item n_centroids - Integer or `NULL`. Number of k-means centroids. If
#'  `NULL`, defaults to `floor(4 * sqrt(n_cells))`. Defaults to `NULL`.
#'  \item k_means_iter - Integer. Maximum number of k-means iterations. Defaults
#'  to `50L`.
#'  \item k_means_init - String or `NULL`. Initialisation method. One of
#'  `"random"`, `"parallel"` or `"plusplus"`. If `NULL`, picked on the Rust side
#'  based on the number of centroids. Defaults to `NULL`.
#'  \item fixed - Boolean. Shall k-means run for a fixed number of iterations,
#'  without checking for convergence. wgpu only; MLX always runs every
#'  iteration. Defaults to `TRUE`.
#'  \item quantise - Boolean. Shall the data buffer be held at fp16 on the GPU.
#'  Halves the buffer and helps when the assignment kernels are memory bound.
#'  wgpu only. Defaults to `FALSE`.
#'  \item dist - String. Distance for the k-means and the centroid graph. One of
#'  `c("euclidean", "cosine")`. Defaults to `"euclidean"`.
#'  \item cell_mediated - Boolean. Shall the cell-mediated centroid graph from
#'  Secuer be built instead of the kNN graph on the centroids. Centroids are
#'  then linked by the cells that sit near both, so two centroids that are close
#'  in space but have no cells between them stay apart. If `TRUE`, `centroid_k`
#'  and `centroid_graph` are ignored. Defaults to `FALSE`.
#'  \item n_anchors - Integer. Number of nearest centroids each cell links to in
#'  the cell-mediated graph. Only used if `cell_mediated = TRUE`. Defaults to
#'  `5L`.
#'  \item centroid_k - Integer. Neighbours per centroid in the exact centroid
#'  kNN. Only used if `cell_mediated = FALSE`. Defaults to `15L`.
#'  \item The elements of the base list, overridden by `centroid_graph`, spliced
#'  in at this position.
#'  \item algorithm - String. Community detection on the centroid graph. One of
#'  `c("louvain", "leiden")`. Defaults to `"louvain"`.
#'  \item n_iterations - Integer or `NULL`. Number of iterations of the
#'  community detection. A negative value iterates until stable. If `NULL`, the
#'  bixverse default for the chosen `algorithm`. Defaults to `NULL`.
#'  \item beta - Numeric. Leiden only. Randomness of the refinement step.
#'  Defaults to `0.01`.
#'  \item min_gain - Numeric. With a negative `n_iterations`, also stop once an
#'  iteration gains no more than this in modularity. Defaults to `0.0`.
#'  \item local_moving - String. `"queue"` is Traag's sequential queue.
#'  `"coloured"` moves the nodes of one colour class in parallel, which only
#'  kicks in on larger levels of the graph. One of `c("queue", "coloured")`.
#'  Defaults to `"queue"`.
#'  \item multi_level - Boolean. Shall the communities be aggregated and refined
#'  in levels. Defaults to `TRUE`.
#'  \item max_evals - Integer. Cap on the node evaluations per local moving
#'  phase, in units of the number of nodes. Defaults to `10L`.
#' }
#'
#' @references Wei, et al., PLoS Comput Biol, 2022.
#'
#' @export
params_sc_fast_cluster_gpu <- function(
  n_centroids = NULL,
  k_means_iter = 50L,
  k_means_init = NULL,
  fixed = TRUE,
  quantise = FALSE,
  dist = c("euclidean", "cosine"),
  cell_mediated = FALSE,
  n_anchors = 5L,
  centroid_k = 15L,
  centroid_graph = list(),
  algorithm = c("louvain", "leiden"),
  n_iterations = NULL,
  beta = 0.01,
  min_gain = 0.0,
  local_moving = c("queue", "coloured"),
  multi_level = TRUE,
  max_evals = 10L
) {
  dist <- match.arg(dist)
  algorithm <- match.arg(algorithm)
  local_moving <- match.arg(local_moving)

  # Checks
  checkmate::qassert(n_centroids, c("I1[2,)", "0"))
  checkmate::qassert(k_means_iter, "I1[1,)")
  checkmate::qassert(k_means_init, c("S1", "0"))
  checkmate::qassert(fixed, "B1")
  checkmate::qassert(quantise, "B1")
  checkmate::assertChoice(dist, c("euclidean", "cosine"))
  checkmate::qassert(cell_mediated, "B1")
  checkmate::qassert(n_anchors, "I1[1,)")
  checkmate::qassert(centroid_k, "I1[1,)")
  checkmate::assertChoice(algorithm, c("louvain", "leiden"))
  checkmate::qassert(n_iterations, c("I1", "0"))
  checkmate::qassert(beta, "N1(0,)")
  checkmate::qassert(min_gain, "N1[0,)")
  checkmate::assertChoice(local_moving, c("queue", "coloured"))
  checkmate::qassert(multi_level, "B1")
  checkmate::qassert(max_evals, "I1[1,)")

  # Merge
  centroid_graph <- utils::modifyList(
    bixverse::params_knn_graph_defaults(),
    centroid_graph,
    keep.null = TRUE
  )

  if (!is.null(k_means_init)) {
    checkmate::assertChoice(k_means_init, c("random", "parallel", "plusplus"))
  }
  bixverse:::assertKnnGraphParams(centroid_graph)

  # Return
  c(
    list(
      n_centroids = n_centroids,
      k_means_iter = k_means_iter,
      k_means_init = k_means_init,
      fixed = fixed,
      quantise = quantise,
      dist = dist,
      cell_mediated = cell_mediated,
      n_anchors = n_anchors,
      centroid_k = centroid_k
    ),
    centroid_graph,
    list(
      algorithm = algorithm,
      n_iterations = n_iterations,
      beta = beta,
      min_gain = min_gain,
      local_moving = local_moving,
      multi_level = multi_level,
      max_evals = max_evals
    )
  )
}

#' Wrapper function for the GPU fastMNN parameters
#'
#' @description GPU counterpart to [bixverse::params_sc_fastmnn()]. Same fastMNN
#' knobs minus the PCA ones, since the GPU path corrects the PCA already stored
#' in the object. The kNN block is the GPU one, see [params_knn_gpu_defaults()],
#' with `k` and `ann_dist` defaulting to the CPU values.
#'
#' @details
#' Every search in fastMNN is a cross-query between two sets of cells, so
#' `knn_method = "nndescent"` builds and beam searches a CAGRA graph here. `k =
#' 0L` is rejected, since fastMNN has no data-driven fallback for it.
#'
#' @param ndist Numeric. Number of median distances for the tricube kernel
#' bandwidth. Defaults to `3.0`.
#' @param cos_norm Boolean. Apply cosine normalisation before computing
#' distances. Defaults to `TRUE`.
#' @param knn List. Optional overrides for the kNN block. See
#' [params_knn_gpu_defaults()] for the available elements. Unknown elements are
#' an error. Defaults to `list()`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item ndist - Numeric. Number of median distances for the tricube kernel
#'  bandwidth. Defaults to `3.0`.
#'  \item cos_norm - Boolean. Apply cosine normalisation before computing
#'  distances. Defaults to `TRUE`.
#'  \item The elements of [params_knn_gpu_defaults()], overridden by `knn`,
#'  spliced in at this position.
#' }
#'
#' @references Haghverdi, et al., Nat Biotechnol, 2018
#'
#' @export
params_sc_fastmnn_gpu <- function(
  ndist = 3.0,
  cos_norm = TRUE,
  knn = list()
) {
  # Checks
  checkmate::qassert(ndist, "N1(0,)")
  checkmate::qassert(cos_norm, "B1")

  # Merge
  knn_base <- params_knn_gpu_defaults()
  checkmate::assertSubset(names(knn), names(knn_base))
  knn <- utils::modifyList(
    knn_base,
    utils::modifyList(
      list(k = 20L, ann_dist = "cosine"),
      knn,
      keep.null = TRUE
    ),
    keep.null = TRUE
  )

  # Return
  c(
    list(
      ndist = ndist,
      cos_norm = cos_norm
    ),
    knn
  )
}

#' Default parameters for Harmony v2 GPU batch correction
#'
#' @param k Integer or `NULL`. Number of clusters for k-means clustering. If not
#' provided, it will be automatically determined as `min(round(N / 30), 100)`.
#' Defaults to `NULL`.
#' @param sigma Numeric vector. Per-cluster diversity weights. Either a single
#' value (broadcast to all clusters) or a vector of length k. Defaults to `0.1`.
#' @param theta Numeric vector. Per-variable diversity penalty. Must be a single
#' value; only one batch covariate is supported on the GPU path. Defaults to
#' `2.0`.
#' @param lambda Numeric vector. Ridge regression penalty for the linear model.
#' Typically a single value. Ignored when `use_dynamic_lambda = TRUE`. Defaults
#' to `1.0`.
#' @param max_iter_kmeans Integer. Maximum number of k-means Jacobi sweeps per
#' Harmony round. Defaults to `4L`.
#' @param max_iter_harmony Integer. Maximum number of Harmony outer iterations.
#' Defaults to `10L`.
#' @param epsilon_kmeans Numeric. Convergence threshold for k-means clustering.
#' Defaults to `0.001`.
#' @param epsilon_harmony Numeric. Convergence threshold for Harmony. Defaults
#' to `0.01`.
#' @param window_size Integer. Number of previous iterations to consider when
#' checking convergence. Defaults to `3L`.
#' @param alpha Numeric. Scaling factor for dynamic lambda estimation. Must be
#' in (0, 1). Only relevant when `use_dynamic_lambda = TRUE`. Defaults to `0.2`.
#' @param tau Numeric. Scaling factor for theta based on batch size. A value of
#' 0 disables batch-size scaling of theta. Defaults to `0.0`.
#' @param batch_proportion_cutoff Numeric. Cutoff for pruning batches with small
#' proportions during ridge regression. Defaults to `1e-05`.
#' @param use_dynamic_lambda Boolean. If `TRUE`, lambda is estimated dynamically
#' per cluster instead of using the fixed `lambda` value. Defaults to `FALSE`.
#' @param csr_cube_count Integer. Number of parallel thread groups used when
#' building the level-CSR index on the GPU. Adjust for your hardware if needed.
#' Defaults to `256L`.
#' @param k_means_iter Integer. Maximum number of k-means iterations for the
#' initial centroid computation. Defaults to `10L`.
#' @param k_means_init String or `NULL`. Initialisation strategy for k-means.
#' Defaults to `NULL`.
#' @param fixed Boolean. If `TRUE`, centroids are fixed after initialisation.
#' Defaults to `FALSE`.
#' @param quantise Boolean. If `TRUE`, quantises intermediate values to f16
#' during k-means. Defaults to `FALSE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item k - Integer or `NULL`. Number of clusters for k-means clustering. If
#'  not provided, it will be automatically determined as `min(round(N / 30),
#'  100)`. Defaults to `NULL`.
#'  \item sigma - Numeric vector. Per-cluster diversity weights. Either a single
#'  value (broadcast to all clusters) or a vector of length k. Defaults to
#'  `0.1`.
#'  \item theta - Numeric vector. Per-variable diversity penalty. Must be a
#'  single value; only one batch covariate is supported on the GPU path.
#'  Defaults to `2.0`.
#'  \item lambda - Numeric vector. Ridge regression penalty for the linear
#'  model. Typically a single value. Ignored when `use_dynamic_lambda = TRUE`.
#'  Defaults to `1.0`.
#'  \item max_iter_kmeans - Integer. Maximum number of k-means Jacobi sweeps per
#'  Harmony round. Defaults to `4L`.
#'  \item max_iter_harmony - Integer. Maximum number of Harmony outer
#'  iterations. Defaults to `10L`.
#'  \item epsilon_kmeans - Numeric. Convergence threshold for k-means
#'  clustering. Defaults to `0.001`.
#'  \item epsilon_harmony - Numeric. Convergence threshold for Harmony. Defaults
#'  to `0.01`.
#'  \item window_size - Integer. Number of previous iterations to consider when
#'  checking convergence. Defaults to `3L`.
#'  \item alpha - Numeric. Scaling factor for dynamic lambda estimation. Must be
#'  in (0, 1). Only relevant when `use_dynamic_lambda = TRUE`. Defaults to
#'  `0.2`.
#'  \item tau - Numeric. Scaling factor for theta based on batch size. A value
#'  of 0 disables batch-size scaling of theta. Defaults to `0.0`.
#'  \item batch_proportion_cutoff - Numeric. Cutoff for pruning batches with
#'  small proportions during ridge regression. Defaults to `1e-05`.
#'  \item use_dynamic_lambda - Boolean. If `TRUE`, lambda is estimated
#'  dynamically per cluster instead of using the fixed `lambda` value. Defaults
#'  to `FALSE`.
#'  \item csr_cube_count - Integer. Number of parallel thread groups used when
#'  building the level-CSR index on the GPU. Adjust for your hardware if needed.
#'  Defaults to `256L`.
#'  \item k_means_iter - Integer. Maximum number of k-means iterations for the
#'  initial centroid computation. Defaults to `10L`.
#'  \item k_means_init - String or `NULL`. Initialisation strategy for k-means.
#'  Defaults to `NULL`.
#'  \item fixed - Boolean. If `TRUE`, centroids are fixed after initialisation.
#'  Defaults to `FALSE`.
#'  \item quantise - Boolean. If `TRUE`, quantises intermediate values to f16
#'  during k-means. Defaults to `FALSE`.
#' }
#'
#' @export
params_sc_harmony_v2_gpu <- function(
  k = NULL,
  sigma = 0.1,
  theta = 2.0,
  lambda = 1.0,
  max_iter_kmeans = 4L,
  max_iter_harmony = 10L,
  epsilon_kmeans = 0.001,
  epsilon_harmony = 0.01,
  window_size = 3L,
  alpha = 0.2,
  tau = 0.0,
  batch_proportion_cutoff = 1e-05,
  use_dynamic_lambda = FALSE,
  csr_cube_count = 256L,
  k_means_iter = 10L,
  k_means_init = NULL,
  fixed = FALSE,
  quantise = FALSE
) {
  # Checks
  checkmate::qassert(k, c("I1[1,)", "0"))
  checkmate::qassert(sigma, "N+[0,)")
  checkmate::qassert(theta, "N+[0,)")
  checkmate::qassert(lambda, "N+[0,)")
  checkmate::qassert(max_iter_kmeans, "I1[1,)")
  checkmate::qassert(max_iter_harmony, "I1[1,)")
  checkmate::qassert(epsilon_kmeans, "N1(0,)")
  checkmate::qassert(epsilon_harmony, "N1(0,)")
  checkmate::qassert(window_size, "I1[1,)")
  checkmate::qassert(alpha, "N1(0,1)")
  checkmate::qassert(tau, "N1[0,)")
  checkmate::qassert(batch_proportion_cutoff, "N1(0,)")
  checkmate::qassert(use_dynamic_lambda, "B1")
  checkmate::qassert(csr_cube_count, "I1[1,)")
  checkmate::qassert(k_means_iter, "I1[1,)")
  checkmate::qassert(k_means_init, c("S1", "0"))
  checkmate::qassert(fixed, "B1")
  checkmate::qassert(quantise, "B1")

  # Return
  list(
    k = k,
    sigma = sigma,
    theta = theta,
    lambda = lambda,
    max_iter_kmeans = max_iter_kmeans,
    max_iter_harmony = max_iter_harmony,
    epsilon_kmeans = epsilon_kmeans,
    epsilon_harmony = epsilon_harmony,
    window_size = window_size,
    alpha = alpha,
    tau = tau,
    batch_proportion_cutoff = batch_proportion_cutoff,
    use_dynamic_lambda = use_dynamic_lambda,
    csr_cube_count = csr_cube_count,
    k_means_iter = k_means_iter,
    k_means_init = k_means_init,
    fixed = fixed,
    quantise = quantise
  )
}

#' Wrapper function to generate t-SNE parameters (GPU version)
#'
#' @param lr Numeric or `NULL`. Learning rate. If `NULL` (the default), the Rust
#' backend sets it to `max((n_samples / 12), 200)`, following the N-dependent
#' heuristic of Belkina et al. (2019). Defaults to `NULL`.
#' @param n_epochs Integer. Number of optimisation epochs. Defaults to `1000L`.
#' @param early_exag_iter Integer. Number of early exaggeration iterations.
#' Defaults to `250L`.
#' @param early_exag_factor Numeric. Early exaggeration factor. Defaults to
#' `12.0`.
#' @param late_exag_factor Numeric or `NULL`. If you wish to also use late
#' exaggerations. Can be useful on large data sets (set it to `2.0` to `4.0`).
#' Defaults to `NULL`.
#' @param theta Numeric. Barnes-Hut approximation angle. Lower values increase
#' accuracy at the cost of speed. Defaults to `0.5`.
#' @param n_interp_points Integer. Number of interpolation points per grid cell
#' for FFT acceleration (`"fft"`, `"fft_3k"` and `"fft_3k_gpu"`). Defaults to
#' `3L`.
#' @param max_depth Integer. Maximum Barnes-Hut tree depth for the
#' quick-and-dirty optimiser (`"bh_qd"`). Smaller is faster and coarser; qdtsne
#' recommends `7` to `10`. No effect on the other optimisers. Defaults to `7L`.
#' @param init String. Embedding initialisation method. One of `c("pca",
#' "spectral", "random")`. Defaults to `"pca"`.
#' @param randomised Boolean. Use randomised SVD for PCA initialisation.
#' Defaults to `TRUE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item lr - Numeric or `NULL`. Learning rate. If `NULL` (the default), the
#'  Rust backend sets it to `max((n_samples / 12), 200)`, following the
#'  N-dependent heuristic of Belkina et al. (2019). Defaults to `NULL`.
#'  \item n_epochs - Integer. Number of optimisation epochs. Defaults to
#'  `1000L`.
#'  \item early_exag_iter - Integer. Number of early exaggeration iterations.
#'  Defaults to `250L`.
#'  \item early_exag_factor - Numeric. Early exaggeration factor. Defaults to
#'  `12.0`.
#'  \item late_exag_factor - Numeric or `NULL`. If you wish to also use late
#'  exaggerations. Can be useful on large data sets (set it to `2.0` to `4.0`).
#'  Defaults to `NULL`.
#'  \item theta - Numeric. Barnes-Hut approximation angle. Lower values increase
#'  accuracy at the cost of speed. Defaults to `0.5`.
#'  \item n_interp_points - Integer. Number of interpolation points per grid
#'  cell for FFT acceleration (`"fft"`, `"fft_3k"` and `"fft_3k_gpu"`). Defaults
#'  to `3L`.
#'  \item max_depth - Integer. Maximum Barnes-Hut tree depth for the
#'  quick-and-dirty optimiser (`"bh_qd"`). Smaller is faster and coarser; qdtsne
#'  recommends `7` to `10`. No effect on the other optimisers. Defaults to `7L`.
#'  \item init - String. Embedding initialisation method. One of `c("pca",
#'  "spectral", "random")`. Defaults to `"pca"`.
#'  \item randomised - Boolean. Use randomised SVD for PCA initialisation.
#'  Defaults to `TRUE`.
#' }
#'
#' @references Belkina, et al., Nat. Commun., 2019
#'
#' @export
params_tsne_gpu <- function(
  lr = NULL,
  n_epochs = 1000L,
  early_exag_iter = 250L,
  early_exag_factor = 12.0,
  late_exag_factor = NULL,
  theta = 0.5,
  n_interp_points = 3L,
  max_depth = 7L,
  init = c("pca", "spectral", "random"),
  randomised = TRUE
) {
  init <- match.arg(init)

  # Checks
  checkmate::qassert(lr, c("N1", "0"))
  checkmate::qassert(n_epochs, "I1[1,)")
  checkmate::qassert(early_exag_iter, "I1[1,)")
  checkmate::qassert(early_exag_factor, "N1")
  checkmate::qassert(late_exag_factor, c("N1", "0"))
  checkmate::qassert(theta, "N1[0,1]")
  checkmate::qassert(n_interp_points, "I1[1,)")
  checkmate::qassert(max_depth, "I1[1,)")
  checkmate::assertChoice(init, c("pca", "spectral", "random"))
  checkmate::qassert(randomised, "B1")

  # Return
  list(
    lr = lr,
    n_epochs = n_epochs,
    early_exag_iter = early_exag_iter,
    early_exag_factor = early_exag_factor,
    late_exag_factor = late_exag_factor,
    theta = theta,
    n_interp_points = n_interp_points,
    max_depth = max_depth,
    init = init,
    randomised = randomised
  )
}

#' Wrapper function to generate UMAP parameters (GPU version)
#'
#' @param local_connectivity Numeric. Number of nearest neighbours assumed to be
#' at distance zero. Defaults to `1.0`.
#' @param bandwidth Numeric. Convergence tolerance for smooth kNN distance
#' binary search. Defaults to `1e-05`.
#' @param mix_weight Numeric. Balance between fuzzy union and directed graph
#' during symmetrisation. Defaults to `1.0`.
#' @param lr Numeric. Learning rate. Defaults to `1.0`.
#' @param n_epochs Integer or `NULL`. Number of optimisation epochs. Defaults to
#' `NULL`.
#' @param neg_sample_rate Integer. Number of negative samples per positive
#' sample. Defaults to `5L`.
#' @param gamma Numeric. Repulsion strength. Defaults to `1.0`.
#' @param optimiser String. The optimiser for the embedding. One of
#' `c("adam_gpu", "adam_parallel", "sgd", "adam")`. Defaults to `"adam_gpu"`.
#' @param init String. Embedding initialisation method. One of `c("spectral",
#' "pca", "random")`. Defaults to `"spectral"`.
#' @param randomised Boolean. Use randomised SVD for PCA initialisation.
#' Defaults to `FALSE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item local_connectivity - Numeric. Number of nearest neighbours assumed to
#'  be at distance zero. Defaults to `1.0`.
#'  \item bandwidth - Numeric. Convergence tolerance for smooth kNN distance
#'  binary search. Defaults to `1e-05`.
#'  \item mix_weight - Numeric. Balance between fuzzy union and directed graph
#'  during symmetrisation. Defaults to `1.0`.
#'  \item lr - Numeric. Learning rate. Defaults to `1.0`.
#'  \item n_epochs - Integer or `NULL`. Number of optimisation epochs. Defaults
#'  to `NULL`.
#'  \item neg_sample_rate - Integer. Number of negative samples per positive
#'  sample. Defaults to `5L`.
#'  \item gamma - Numeric. Repulsion strength. Defaults to `1.0`.
#'  \item optimiser - String. The optimiser for the embedding. One of
#'  `c("adam_gpu", "adam_parallel", "sgd", "adam")`. Defaults to `"adam_gpu"`.
#'  \item init - String. Embedding initialisation method. One of `c("spectral",
#'  "pca", "random")`. Defaults to `"spectral"`.
#'  \item randomised - Boolean. Use randomised SVD for PCA initialisation.
#'  Defaults to `FALSE`.
#' }
#'
#' @export
params_umap_gpu <- function(
  local_connectivity = 1.0,
  bandwidth = 1e-05,
  mix_weight = 1.0,
  lr = 1.0,
  n_epochs = NULL,
  neg_sample_rate = 5L,
  gamma = 1.0,
  optimiser = c("adam_gpu", "adam_parallel", "sgd", "adam"),
  init = c("spectral", "pca", "random"),
  randomised = FALSE
) {
  optimiser <- match.arg(optimiser)
  init <- match.arg(init)

  # Checks
  checkmate::qassert(local_connectivity, "N1")
  checkmate::qassert(bandwidth, "N1")
  checkmate::qassert(mix_weight, "N1")
  checkmate::qassert(lr, "N1")
  checkmate::qassert(n_epochs, c("I1[1,)", "0"))
  checkmate::qassert(neg_sample_rate, "I1")
  checkmate::qassert(gamma, "N1")
  checkmate::assertChoice(
    optimiser,
    c("adam_gpu", "adam_parallel", "sgd", "adam")
  )
  checkmate::assertChoice(init, c("spectral", "pca", "random"))
  checkmate::qassert(randomised, "B1")

  # Return
  list(
    local_connectivity = local_connectivity,
    bandwidth = bandwidth,
    mix_weight = mix_weight,
    lr = lr,
    n_epochs = n_epochs,
    neg_sample_rate = neg_sample_rate,
    gamma = gamma,
    optimiser = optimiser,
    init = init,
    randomised = randomised
  )
}
